<script setup lang="ts">
type Regime='current'|'ccdii'|'ledger'
type Tx={id:number;at:string;label:string;amount:number;outcome:'pending'|'delivered'|'disputed'|'fraud';outcomeAt:string;paidAt:string}
type GovernanceKey='annualProfit'|'externalHarm'|'bonus'|'longTermPay'|'clawback'|'personalLiability'|'oversight'|'provision'|'horizon'
const props=withDefaults(defineProps<{locale?:'nl'|'en';mode?:'both'|'transaction'|'governance'}>(),{locale:'nl',mode:'both'})
const nl=computed(()=>props.locale==='nl')
const tx=reactive({balance:900,capacity:1200,committed:550,personalLimit:750})
const transactions=ref<Tx[]>([
 {id:1,at:'2026-09-17T09:10',label:'Webshop',amount:180,outcome:'delivered',outcomeAt:'2026-09-19T14:20',paidAt:'2026-09-19T16:00'},
 {id:2,at:'2026-09-17T12:35',label:'Fietsreparatie',amount:320,outcome:'delivered',outcomeAt:'2026-09-17T17:10',paidAt:'2026-09-18T09:00'},
 {id:3,at:'2026-09-17T12:36',label:'Laptop',amount:950,outcome:'fraud',outcomeAt:'2026-09-20T11:30',paidAt:''},
 {id:4,at:'2026-09-18T08:20',label:'Boodschappen',amount:85,outcome:'pending',outcomeAt:'',paidAt:''}
])
let nextId=5
const money=(v:number)=>new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v)
const simulate=(selected:Regime)=>{let own=Math.max(0,tx.balance),credit=Math.max(0,Math.min(tx.capacity-tx.committed,tx.personalLimit));return [...transactions.value].sort((a,b)=>a.at.localeCompare(b.at)||a.id-b.id).map(item=>{const ownNeeded=selected==='ledger'?Math.min(item.amount,own):0;const creditNeeded=selected==='ledger'?Math.max(0,item.amount-ownNeeded):item.amount;const accepted=selected==='current'||creditNeeded<=credit;if(accepted){if(selected==='ledger')own-=ownNeeded;if(selected!=='current')credit-=creditNeeded}return{...item,ownNeeded,creditNeeded,accepted,ownAfter:own,creditAfter:credit}})}
const comparison=computed(()=>{const current=simulate('current'),ccdii=simulate('ccdii'),ledger=simulate('ledger');return current.map((item,index)=>({item,current:item,ccdii:ccdii[index],ledger:ledger[index]}))})
const addTransaction=()=>{const last=[...transactions.value].sort((a,b)=>a.at.localeCompare(b.at)).at(-1);const d=new Date(last?.at||'2026-09-17T09:00');d.setMinutes(d.getMinutes()+45);const delivery=new Date(d);delivery.setDate(delivery.getDate()+2);const paid=new Date(delivery);paid.setDate(paid.getDate()+1);transactions.value.push({id:nextId++,at:d.toISOString().slice(0,16),label:nl.value?'Nieuwe aankoop':'New purchase',amount:250,outcome:'delivered',outcomeAt:delivery.toISOString().slice(0,16),paidAt:paid.toISOString().slice(0,16)})}
const removeTransaction=(id:number)=>{transactions.value=transactions.value.filter(x=>x.id!==id)}
const chart=computed(()=>{const current=simulate('current').filter(x=>x.accepted),ccdii=simulate('ccdii').filter(x=>x.accepted),ledger=simulate('ledger').filter(x=>x.accepted);const stamps=transactions.value.flatMap(x=>[x.at,x.outcomeAt,x.paidAt]).filter(Boolean).map(x=>new Date(x).getTime()).filter(Number.isFinite);const start=stamps.length?Math.min(...stamps):Date.now(),end=(stamps.length?Math.max(...stamps,start+7*86400000):start+7*86400000)+2*86400000;const points=Array.from({length:15},(_,i)=>start+(end-start)*i/14);const openTraditional=(items:ReturnType<typeof simulate>,t:number)=>items.reduce((sum,x)=>{const buy=new Date(x.at).getTime(),close=x.paidAt?new Date(x.paidAt).getTime():Infinity;return sum+(t>=buy&&t<close?x.amount:0)},0);const openLedger=(t:number,kind:'reserve'|'debt')=>ledger.reduce((sum,x)=>{const buy=new Date(x.at).getTime(),out=x.outcomeAt?new Date(x.outcomeAt).getTime():Infinity,close=x.paidAt?new Date(x.paidAt).getTime():Infinity;if(kind==='reserve'){const release=x.outcome==='delivered'?out:close;return sum+(t>=buy&&t<release?x.ownNeeded:0)}return sum+(x.outcome==='delivered'&&t>=out&&t<close?x.creditNeeded:0)},0);const series={current:points.map(t=>openTraditional(current,t)),ccdii:points.map(t=>openTraditional(ccdii,t)),reserve:points.map(t=>openLedger(t,'reserve')),ledgerDebt:points.map(t=>openLedger(t,'debt'))};const max=Math.max(1,...series.current,...series.ccdii,...series.reserve,...series.ledgerDebt);const line=(values:number[])=>values.map((v,i)=>`${28+i*34},${155-v/max*120}`).join(' ');return{points,series,max,line,first:new Date(start).toLocaleDateString(nl.value?'nl-NL':'en-GB',{day:'numeric',month:'short'}),last:new Date(end).toLocaleDateString(nl.value?'nl-NL':'en-GB',{day:'numeric',month:'short'})}})
const governance=reactive({annualProfit:20,externalHarm:30,bonus:25,longTermPay:25,clawback:30,personalLiability:15,oversight:55,provision:30,horizon:3})
const activeGovernance=ref<GovernanceKey>('bonus')
const governanceHelp=computed(()=>({
 annualProfit:{title:nl.value?'Jaarwinst':'Annual profit',text:nl.value?'Vergroot de winst waarop directe en uitgestelde beloning worden berekend. De maatschappelijke schade verandert hierdoor niet automatisch.':'Increases the profit on which immediate and deferred compensation are calculated. Societal harm does not automatically change with it.'},
 externalHarm:{title:nl.value?'Verwachte externe schade':'Expected external harm',text:nl.value?'Vergroot de gevolgen die buiten de onderneming terechtkomen. Alleen het deel met een voorziening wordt in dit model vooraf gedekt.':'Increases consequences borne outside the company. Only the provisioned share is covered in advance in this model.'},
 bonus:{title:nl.value?'Directe bonusdruk':'Immediate bonus pressure',text:nl.value?'Een hogere waarde brengt meer beloning naar het heden. Dat vergroot de prikkel om resultaten te boeken voordat latere gevolgen zichtbaar zijn.':'A higher value moves more reward into the present, strengthening incentives to produce results before later consequences appear.'},
 longTermPay:{title:nl.value?'Uitgestelde beloning':'Deferred compensation',text:nl.value?'Een groter deel van de beloning blijft langer verbonden aan latere resultaten en gevolgen.':'A larger share of compensation remains connected to later results and consequences.'},
 clawback:{title:'Clawback',text:nl.value?'Geeft aan hoeveel reeds toegekende beloning kan worden teruggevorderd wanneer later schade of verkeerd handelen blijkt.':'Indicates how much awarded compensation can be recovered when harm or misconduct emerges later.'},
 personalLiability:{title:nl.value?'Persoonlijke aansprakelijkheid':'Personal liability',text:nl.value?'Versterkt de mate waarin beslissers zelf gevolgen kunnen dragen, naast de aansprakelijkheid van de onderneming.':'Strengthens the extent to which decision-makers can bear consequences personally, alongside corporate liability.'},
 oversight:{title:nl.value?'Onafhankelijk toezicht':'Independent oversight',text:nl.value?'Vergroot de kans dat risico’s, belangenconflicten en uitgestelde gevolgen buiten de directe commerciële prikkel worden beoordeeld.':'Increases scrutiny of risks, conflicts and delayed consequences outside the immediate commercial incentive.'},
 provision:{title:nl.value?'Voorziening voor schade':'Provision for harm',text:nl.value?'Reserveert vooraf een groter deel van de verwachte schade. Dit vermindert de ongedekte schade, niet de schade zelf.':'Sets aside a larger share of expected harm in advance. This reduces uncovered harm, not the harm itself.'},
 horizon:{title:nl.value?'Moment waarop gevolgen blijken':'When consequences emerge',text:nl.value?'Verplaatst het moment waarop schade zichtbaar wordt. Een langere termijn maakt kortlopende beloning en verantwoordelijkheid makkelijker van elkaar los te koppelen.':'Moves the point at which harm becomes visible. A longer horizon makes it easier for short-term reward and accountability to become detached.'}
})[activeGovernance.value])
const shortReward=computed(()=>Math.round(governance.annualProfit*governance.bonus/100*10)/10)
const delayedReward=computed(()=>Math.round(governance.annualProfit*governance.longTermPay/100*10)/10)
const coveredHarm=computed(()=>Math.round(governance.externalHarm*governance.provision/100*10)/10)
const accountabilityGap=computed(()=>Math.round((governance.externalHarm*(100-governance.provision)/100)*(1-(governance.clawback+governance.personalLiability+governance.oversight)/300)*10)/10)
const alignment=computed(()=>Math.max(0,Math.min(100,Math.round((governance.longTermPay+governance.clawback+governance.personalLiability+governance.oversight+governance.provision)/5-(governance.bonus-governance.longTermPay)*.25))))
</script>

<template>
 <section class="risk-model" data-analytics-model="risk-responsibility">
  <header><p>{{props.mode==='both'?(nl?'TWEE SCHALEN':'TWO SCALES'):(nl?'SCENARIOVERKENNER':'SCENARIO EXPLORER')}}</p><h3>{{props.mode==='transaction'?(nl?'Veilig reserveren door de tijd':'Safe reservation over time'):props.mode==='governance'?(nl?'Beloning en gevolgen door de tijd':'Reward and consequences over time'):(nl?'Financiële veiligheid én bestuurlijke afstemming':'Financial safety and governance alignment')}}</h3><span>{{nl?'De verkenner gebruikt didactische aannames. Zij toont relaties, geen kredietbesluit of moreel eindoordeel.':'The explorer uses teaching assumptions. It shows relationships, not a credit decision or final moral verdict.'}}</span></header>
  <section v-if="props.mode!=='governance'" class="model-section">
   <div class="section-head"><b>1</b><div><h4>{{nl?'Persoonlijke financiële veiligheid':'Personal financial safety'}}</h4><p>{{nl?'Voeg transacties toe en zie in tijdsvolgorde wanneer eigen geld wordt gereserveerd, krediet nodig wordt en een grens de aankoop weigert.':'Add transactions and see, in time order, when owned funds are reserved, credit becomes necessary and a limit rejects a purchase.'}}</p></div></div>
   <div class="transaction-layout">
    <div class="controls compact">
     <label><span>{{nl?'Eigen vrij geld':'Own available funds'}} <output>{{money(tx.balance)}}</output></span><input v-model.number="tx.balance" type="range" min="0" max="3000" step="50"></label>
     <label><span>{{nl?'Maximale kredietcapaciteit':'Maximum credit capacity'}} <output>{{money(tx.capacity)}}</output></span><input v-model.number="tx.capacity" type="range" min="0" max="3000" step="50"></label>
     <label><span>{{nl?'Al gecommitteerd':'Already committed'}} <output>{{money(tx.committed)}}</output></span><input v-model.number="tx.committed" type="range" min="0" :max="tx.capacity" step="50"></label>
     <label><span>{{nl?'Persoonlijke kredietgrens':'Personal credit limit'}} <output>{{money(tx.personalLimit)}}</output></span><input v-model.number="tx.personalLimit" type="range" min="0" max="2000" step="50"></label>
    </div>
    <div class="transaction-editor">
     <div class="editor-head"><strong>{{nl?'Transacties':'Transactions'}}</strong><button @click="addTransaction">＋ {{nl?'Toevoegen':'Add'}}</button></div>
     <div v-for="item in transactions" :key="item.id" class="tx-edit"><input v-model="item.at" type="datetime-local" :aria-label="nl?'Besteldatum en tijd':'Order date and time'"><input v-model="item.label" :aria-label="nl?'Omschrijving':'Description'"><label>€ <input v-model.number="item.amount" type="number" min="0" step="5" :aria-label="nl?'Bedrag':'Amount'"></label><select v-model="item.outcome" :aria-label="nl?'Afleverstatus':'Delivery status'"><option value="pending">{{nl?'Onderweg':'Pending'}}</option><option value="delivered">{{nl?'Geleverd':'Delivered'}}</option><option value="disputed">{{nl?'Betwist':'Disputed'}}</option><option value="fraud">{{nl?'Niet geleverd / mogelijke fraude':'Not delivered / possible fraud'}}</option></select><input v-model="item.outcomeAt" type="datetime-local" :disabled="item.outcome==='pending'" :aria-label="nl?'Datum levering, betwisting of melding':'Delivery, dispute or report date'"><input v-model="item.paidAt" type="datetime-local" :disabled="item.outcome==='pending'" :aria-label="item.outcome==='delivered'?(nl?'Betaaldatum':'Payment date'):(nl?'Datum oplossing of terugbetaling':'Resolution or refund date')"><button :aria-label="nl?'Verwijderen':'Remove'" @click="removeTransaction(item.id)">×</button></div>
    </div>
   </div>
   <div class="scenario-comparison">
    <div class="scenario-head"><strong>{{nl?'Gevolg per transactie':'Result per transaction'}}</strong><span>{{nl?'Huidig':'Current'}}</span><span>{{nl?'CCDII-voorstel':'CCDII bill'}}</span><span>{{nl?'Reserveringsmodel':'Reservation model'}}</span></div>
    <article v-for="row in comparison" :key="row.item.id" :class="{fraud:row.item.outcome==='fraud'}">
     <div><time>{{row.item.at.replace('T',' · ')}}</time><strong>{{row.item.label}} · {{money(row.item.amount)}}</strong><small v-if="row.item.outcome==='fraud'">{{nl?'niet geleverd; terugbetaling onzeker zolang geen oplossing is ingevuld':'not delivered; refund uncertain while no resolution is entered'}}</small></div>
     <p :data-label="nl?'HUIDIG':'CURRENT'">{{nl?'Aanbieder beslist afzonderlijk; volledige verplichting kan openblijven.':'Provider decides separately; the full obligation may remain open.'}}</p>
     <p :data-label="nl?'CCDII-VOORSTEL':'CCDII BILL'" :class="{rejected:!row.ccdii.accepted}">{{row.ccdii.accepted?(nl?'Volledig als krediet getoetst en geregistreerd.':'Assessed and recorded in full as credit.'):(nl?'Geweigerd door beschikbare kredietruimte.':'Rejected because of available credit capacity.')}}</p>
     <p :data-label="nl?'RESERVERINGSMODEL':'RESERVATION MODEL'" :class="{rejected:!row.ledger.accepted}"><template v-if="row.ledger.accepted">{{money(row.ledger.ownNeeded)}} {{nl?'eigen geld gereserveerd':'owned funds reserved'}}<template v-if="row.ledger.creditNeeded"> · {{money(row.ledger.creditNeeded)}} {{nl?'krediet':'credit'}}</template><template v-if="row.item.outcome==='fraud'"> · {{nl?'geen afrekening zonder aanvaarde levering':'no settlement without accepted delivery'}}</template></template><template v-else>{{nl?'Geweigerd door beschikbare kredietruimte.':'Rejected because of available credit capacity.'}}</template></p>
    </article>
   </div>
   <div class="exposure-chart"><div><strong>{{nl?'Openstaande reservering en schuld':'Outstanding reservation and debt'}}</strong><small>{{nl?'Alle scenario’s gebruiken dezelfde transacties. Bij mogelijke fraude blijft de huidige blootstelling zonder ingevulde oplossing open; het reserveringsmodel rekent zonder aanvaarde levering niet af.':'All scenarios use the same transactions. With possible fraud, current exposure remains open until a resolution is entered; the reservation model does not settle without accepted delivery.'}}</small></div><svg viewBox="0 0 520 185" role="img" :aria-label="nl?'Openstaande reserveringen en schulden door de tijd':'Outstanding reservations and debt over time'"><line x1="28" y1="155" x2="504" y2="155"/><line x1="28" y1="35" x2="28" y2="155"/><polyline class="current-line" :points="chart.line(chart.series.current)"/><polyline class="ccdii-line" :points="chart.line(chart.series.ccdii)"/><polyline class="reserve-line" :points="chart.line(chart.series.reserve)"/><polyline class="debt-line" :points="chart.line(chart.series.ledgerDebt)"/><text x="28" y="174">{{chart.first}}</text><text x="504" y="174" text-anchor="end">{{chart.last}}</text><text x="22" y="39" text-anchor="end">{{money(chart.max)}}</text></svg><div class="legend"><span><i class="current-key"></i>{{nl?'huidige blootstelling':'current exposure'}}</span><span><i class="ccdii-key"></i>CCDII {{nl?'schuld':'debt'}}</span><span><i class="reserve-key"></i>{{nl?'gereserveerd eigen geld':'reserved own funds'}}</span><span><i class="debt-key"></i>{{nl?'schuld in reserveringsmodel':'reservation-model debt'}}</span></div></div>
   <p class="mechanism"><strong>{{nl?'Veilige toestandsovergang:':'Safe state transition:'}}</strong> {{nl?'CONTROLEREN → RESERVEREN → VASTLEGGEN. Bij levering: RESERVEREN → LEVEREN → AFREKENEN.':'CHECK → RESERVE → COMMIT. On delivery: RESERVE → DELIVER → SETTLE.'}}</p>
  </section>
  <section v-if="props.mode!=='transaction'" class="model-section governance">
   <div class="section-head"><b>2</b><div><h4>{{nl?'Moraliteit en governance door de tijd':'Morality and governance over time'}}</h4><p>{{nl?'Onderzoek of winst en managementbeloning vroeg ontstaan terwijl schade, herstel en persoonlijke aanspreekbaarheid later of elders landen.':'Explore whether profit and management rewards arrive early while harm, repair and personal accountability land later or elsewhere.'}}</p></div></div>
   <div class="governance-grid">
    <div class="controls">
     <label :class="{active:activeGovernance==='annualProfit'}" @pointerdown="activeGovernance='annualProfit'" @focusin="activeGovernance='annualProfit'"><span>{{nl?'Jaarwinst':'Annual profit'}} <output>{{money(governance.annualProfit)}} mln</output></span><input v-model.number="governance.annualProfit" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='externalHarm'}" @pointerdown="activeGovernance='externalHarm'" @focusin="activeGovernance='externalHarm'"><span>{{nl?'Verwachte externe schade':'Expected external harm'}} <output>{{money(governance.externalHarm)}} mln</output></span><input v-model.number="governance.externalHarm" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='bonus'}" @pointerdown="activeGovernance='bonus'" @focusin="activeGovernance='bonus'"><span>{{nl?'Directe bonusdruk':'Immediate bonus pressure'}} <output>{{governance.bonus}}%</output></span><input v-model.number="governance.bonus" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='longTermPay'}" @pointerdown="activeGovernance='longTermPay'" @focusin="activeGovernance='longTermPay'"><span>{{nl?'Uitgestelde beloning':'Deferred compensation'}} <output>{{governance.longTermPay}}%</output></span><input v-model.number="governance.longTermPay" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='clawback'}" @pointerdown="activeGovernance='clawback'" @focusin="activeGovernance='clawback'"><span>Clawback <output>{{governance.clawback}}%</output></span><input v-model.number="governance.clawback" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='personalLiability'}" @pointerdown="activeGovernance='personalLiability'" @focusin="activeGovernance='personalLiability'"><span>{{nl?'Persoonlijke aansprakelijkheid':'Personal liability'}} <output>{{governance.personalLiability}}%</output></span><input v-model.number="governance.personalLiability" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='oversight'}" @pointerdown="activeGovernance='oversight'" @focusin="activeGovernance='oversight'"><span>{{nl?'Onafhankelijk toezicht':'Independent oversight'}} <output>{{governance.oversight}}%</output></span><input v-model.number="governance.oversight" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='provision'}" @pointerdown="activeGovernance='provision'" @focusin="activeGovernance='provision'"><span>{{nl?'Voorziening voor schade':'Provision for harm'}} <output>{{governance.provision}}%</output></span><input v-model.number="governance.provision" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='horizon'}" @pointerdown="activeGovernance='horizon'" @focusin="activeGovernance='horizon'"><span>{{nl?'Moment waarop gevolgen blijken':'When consequences emerge'}} <output>{{governance.horizon}} {{nl?'jaar':'years'}}</output></span><input v-model.number="governance.horizon" type="range" min="1" max="15"></label>
    </div>
    <div class="governance-result">
     <div class="time-axis"><article><span>{{nl?'NU':'NOW'}}</span><b>+ {{money(shortReward)}} mln</b><small>{{nl?'indicatieve directe managementprikkel':'indicative immediate management incentive'}}</small></article><i></i><article><span>+{{governance.horizon}} {{nl?'JAAR':'YEARS'}}</span><b>{{money(coveredHarm)}} mln</b><small>{{nl?'vooraf gedekte schade':'harm provisioned in advance'}}</small></article><i></i><article class="gap"><span>{{nl?'RESTEREND':'REMAINDER'}}</span><b>{{money(accountabilityGap)}} mln</b><small>{{nl?'illustratieve accountability gap':'illustrative accountability gap'}}</small></article></div>
     <div class="score"><span>{{nl?'Afstemming over tijd':'Alignment over time'}}</span><div><i :style="{width:`${alignment}%`}"></i></div><b>{{alignment}}%</b></div>
     <p>{{nl?'Uitgestelde beloning':'Deferred reward'}}: <b>{{money(delayedReward)}} mln</b>. {{nl?'Een hogere score betekent hier alleen dat de gekozen waarborgen voordeel, tijd en verantwoordelijkheid dichter bij elkaar brengen. Grote schade kan ondanks een goede score onaanvaardbaar blijven.':'A higher score here only means that the selected safeguards bring benefit, time and responsibility closer together. Severe harm may remain unacceptable despite a good score.'}}</p>
     <aside class="governance-help"><span>{{nl?'DEZE INSTELLING':'THIS CONTROL'}}</span><strong>{{governanceHelp.title}}</strong><p>{{governanceHelp.text}}</p></aside>
    </div>
   </div>
  </section>
  <footer>{{nl?'Wijzig één aanname tegelijk. Alle uitkomsten zijn illustratieve indices, geen gemeten kansen, kredietadvies of juridische beoordeling.':'Change one assumption at a time. All outcomes are illustrative indices, not measured probabilities, credit advice or legal assessments.'}}</footer>
 </section>
</template>

